"""Grounded REST API generated by Gemma 4 Swarm"""
from typing import List, Dict, Any, Optional
from task_models import TaskItem

class TaskManagerService:
    def __init__(self):
        self.storage: Dict[str, TaskItem] = {}

    def create_task(self, task_id: str, title: str, desc: str) -> TaskItem:
        item = TaskItem(id=task_id, title=title, description=desc)
        self.storage[task_id] = item
        return item

    def get_task(self, task_id: str) -> Optional[TaskItem]:
        return self.storage.get(task_id)
